import{_ as e,o as a,c as o,a4 as n}from"./chunks/framework.ClGzHnIj.js";const g=JSON.parse('{"title":"Runs","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/en/guide/runs.html"}]]},"headers":[],"relativePath":"en/guide/runs.md","filePath":"en/guide/runs.md","lastUpdated":1792397420000}'),s={name:"en/guide/runs.md"};function r(l,t,i,h,d,c){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="runs" tabindex="-1">Runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;Runs&quot;">​</a></h1><p><strong>Runs</strong> draws one tool&#39;s calls to the model, end to end, as a waterfall: where the time went, call by call, and what each call sent and got back.</p><p><strong>Sidebar item:</strong> Runs (below Live) <strong>Route:</strong> <code>/runs</code><strong>Added in:</strong> v0.8.7 (October 2026) <strong>Requires:</strong> calls on the Live page. Point a tool at <code>http://localhost:11435</code> and let it work. To see what each call sent and got back, switch on <strong>Keep the prompt text</strong> on the Live page first.</p><h2 id="what-s-the-point" tabindex="-1">What&#39;s the point? <a class="header-anchor" href="#what-s-the-point" aria-label="Permalink to &quot;What&#39;s the point?&quot;">​</a></h2><p>An agent on a local model is slow, and the question is always where. In the model? Loading it? Reading a prompt it already read? In the tools between calls? Live shows every call from every tool as it happens; Runs takes one tool&#39;s calls and lays them out in time, so the slow part stands out.</p><h2 id="what-a-run-is" tabindex="-1">What a run is <a class="header-anchor" href="#what-a-run-is" aria-label="Permalink to &quot;What a run is&quot;">​</a></h2><p>A run is one tool&#39;s calls that follow each other within two minutes. A longer pause starts a new run. Inside a run, a <strong>step</strong> starts wherever the tool began a fresh conversation: with the text kept, that is where the next call stops carrying the previous conversation; without it, where a prompt worth keeping found the cache empty while the model stayed loaded.</p><h2 id="reading-the-waterfall" tabindex="-1">Reading the waterfall <a class="header-anchor" href="#reading-the-waterfall" aria-label="Permalink to &quot;Reading the waterfall&quot;">​</a></h2><p>One row per model call, placed in time. Each call&#39;s bar is split into what Ollama reports:</p><ul><li><strong>Waiting</strong>: time the call spent before Ollama worked on it, plus anything Ollama did not account for.</li><li><strong>Loading the model</strong>: the model was not in memory. Often the biggest single cost of a run.</li><li><strong>Reading the prompt</strong>: the part of the prompt that was not in the cache. The cached part costs almost nothing, so it does not show as time; the share is written in the Operation column.</li><li><strong>Writing the answer</strong>.</li></ul><p>Between two calls, a <strong>tools</strong> row is the time from the model&#39;s answer to the tool&#39;s next call, named after the tools the model asked for. An <strong>agent</strong> row is the same gap when no tool was asked for: the tool&#39;s own work. Tool time is measured from outside; nothing inside a tool is traced.</p><p>Flags in red say what went wrong on a call: <strong>model loaded</strong>, <strong>cache empty</strong>, <strong>rejected</strong> (the prompt was larger than the loaded context), <strong>error</strong>.</p><h2 id="what-each-row-opens" tabindex="-1">What each row opens <a class="header-anchor" href="#what-each-row-opens" aria-label="Permalink to &quot;What each row opens&quot;">​</a></h2><p>Click a row and the panel on the right shows it.</p><ul><li><strong>A model call</strong>: its numbers and phases, then <strong>Input</strong> (what was sent: the conversation, the tool schemas, with the point where the prompt stopped matching the previous call) and <strong>Output</strong> (what came back: the answer, the model&#39;s thinking when it shows it, and each tool call with its arguments). Both have a <strong>Pretty</strong> and a <strong>Raw</strong> view.</li><li><strong>A tools row</strong>: each tool the model asked for, with its arguments and the result the tool sent back in its next call.</li></ul><p>Every row has its own address, for example <code>/runs?run=…&amp;row=call-3</code>. <strong>Copy link</strong> puts it on the clipboard; opening it lands on that row. From a call, <strong>Open in Prompt X-ray</strong> shows what its prompt was made of, and the X-ray links back.</p><h2 id="what-it-cannot-see" tabindex="-1">What it cannot see <a class="header-anchor" href="#what-it-cannot-see" aria-label="Permalink to &quot;What it cannot see&quot;">​</a></h2><ul><li>Inside the tools. A database query in the middle of a tool is part of the tools row, not a row of its own.</li><li>Text for calls recorded while <strong>Keep the prompt text</strong> was off. The timings are still exact.</li><li>The answer of a call recorded before Keep text kept answers, when that call ended a conversation: it never came back in a later call.</li></ul>',18)])])}const w=e(s,[["render",r]]);export{g as __pageData,w as default};
